1	/**
2	 * `?match07=1` — Screen 07 approved-picture test (2026-11-17, qa/match/07/NOTES.md), the Screen 08 method.
3	 * REAL 3D proxy geometry of "Dive the Washer Tube", solved from the user's approved Screen 07 and the locked game camera
4	 * (tools/match07/solve_cam07.py → cam07_locked.json, tools/match07/fit_proxies07.py → proj07.json): the purple tube (a
5	 * cylinder along the game's 07 tube axis, radius and ring depths fitted to the painted gold rings), the water plane at
6	 * Benny's water level (the painted S-river, foam banks, bubbles) and the five paddles upper-left (blocks standing out of
7	 * the wall at the painted spots).
8	 * Every surface is textured by camera projection of the user's ORIGINAL approved pixels (HUD, title, Benny and coins
9	 * provisionally filled locally: assets/textures/match07/plate07_hybrid.png) from that locked camera, so the locked view
10	 * shows the approved scenery and a moving camera sees it on geometry (parallax). Surfaces the picture never showed, or
11	 * showed much farther / more edge-on than the moving camera sees them (stretch guard + projector depth test), get
12	 * RING-STRUCTURED tiles unwrapped from the artwork: the painted wall bay repeats every ring spacing along the tube (rings
13	 * stay rings deep inside the tube, no smears), the painted river repeats along the water. The shader undoes the game's
14	 * post chain (PROJ05_INVERSE) and takes no fog. Without the switch nothing in this file runs and the game is unchanged.
15	 */
16	import * as THREE from 'three';
17	import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
18	import { PROJ05_INVERSE, flag05 } from '../vfx/waterRibbon';
19	import type { Course } from './course';
20	
21	interface Layout07 {
22	  camera: { matrixWorld: number[]; fov: number; size: [number, number] };
23	  D: [number, number, number];
24	  U: [number, number, number];
25	  X: [number, number, number];
26	  water: [number, number, number];
27	  tube: { r: number; ax: number; h: number };
28	  rings: Record<string, number>;
29	  paddles: { pos: [number, number, number]; along: number; angleDeg: number; w: number }[];
30	}
31	interface Tiles07 { wall: { theta: [number, number]; along: [number, number]; bay: number }; river: { lateral: [number, number]; along: [number, number] } }
32	
33	export interface Match07 {
34	  group: THREE.Group;
35	  bakeDepth(renderer: THREE.WebGLRenderer): void;
36	  sync(renderer: THREE.WebGLRenderer, w: number, h: number): void;
37	  /** M3 '?m07tube=1': true from the hand-over point on — the plunge tube shows and the fitted proxy ends at its depth */
38	  setPlunge(on: boolean): void;
39	}
40	
41	const VERT = /* glsl */ `
42	uniform mat4 uProjVP;
43	uniform float uCtr[64];   // r16 '?m07nearw=1': river centre line (tube-local x) every uCtrA.y units of depth from uCtrA.x
44	uniform vec3 uCtrA;       // first depth, step, on (z)
45	varying vec4 vProj;
46	varying vec3 vW;
47	varying vec3 vN;
48	varying vec3 vL;
49	varying vec2 vUv;
50	varying float vCtr;
51	void main() {
52	  vUv = uv;
53	  vec4 wp = modelMatrix * vec4(position, 1.0);
54	  vProj = uProjVP * wp;
55	  vW = wp.xyz;
56	  vL = (uGroupInv * wp).xyz;
57	  vCtr = 0.0;
58	  if (uCtrA.z > 0.5) {
59	    float ia = clamp((-vL.z - uCtrA.x) / uCtrA.y, 0.0, 62.999);
60	    int i0 = int(floor(ia));
61	    vCtr = mix(uCtr[i0], uCtr[i0 + 1], ia - float(i0));
62	  }
63	  vN = normalize(mat3(modelMatrix) * normal);
64	  gl_Position = projectionMatrix * viewMatrix * wp;
65	}`;
66	
67	const FRAG = /* glsl */ `
68	uniform sampler2D uPlate;
69	uniform sampler2D uDepth;
70	uniform float uUseDepth;
71	uniform vec2 uNearFar;
72	uniform sampler2D uTile;
73	uniform float uMode;      // 0 = triplanar patch, 1 = tube wall unwrap, 2 = river unwrap
74	uniform float uPatchK;
75	uniform vec4 uTube;       // ax, h, ring R2 depth, bay length
76	uniform vec2 uTheta;      // unwrap angle range (rad): right water line .. left water line over the top
77	uniform vec4 uRiver;      // lateral min, lateral max, along min, along max
78	uniform vec3 uProjPos;
79	uniform vec4 uPjPost;
80	uniform vec2 uPjRes;
81	uniform sampler2D uFill;   // M2 '?m07fill=1': provisional-fill mask of the plate (1 = filled, not original pixels)
82	uniform float uFillTile;  // 1 = on the water, filled plate pixels give way to the river tile
83	uniform vec2 uAng;        // M2 '?m07ang=1': view-vs-projector angle cosines (full plate above x, tile below y); x < 0 = off
84	uniform float uGoldLit;   // M2 '?m07gold=1': paddle blocks shaded as solid polished gold where the picture does not cover them
85	uniform vec3 uKey;        // world direction toward the key light (from the viewer's side and above, so the faces the camera sees are lit)
86	uniform float uClip;      // M3 '?m07tube=1': proxy surfaces end at this depth along the tube axis (the plunge tube continues); 0 = off
87	uniform vec2 uGuard;      // stretch guard thresholds (M1/M2 2.2..4.5; M3 '?m07near=1' tighter)
88	uniform vec2 uFade;       // M3 plunge river: fades out between these arc depths (the game's own water continues into 08)
89	uniform float uNearOn;    // r16 '?m07nearw=1': the level-stretch water tile = the painted NEAR river (near_bank / near_foam)
90	uniform vec4 uNearW;      // river half-width incl. the magenta band, magenta band width, bank-tile period along, foam-tile size
91	uniform float uNearM;     // share of the bank tile's columns that is the magenta band (column 0 = its outer edge)
92	uniform sampler2D uNearTile;
93	uniform sampler2D uFoamTile;
94	uniform vec3 uWF;         // r16 '?m07wfoam=1': foam clouds piled on the lowest wall band — base height, cloud-top height, on (z)
95	uniform vec4 uBand;       // r18 '?m07band=1': S-sweep of the river centre off Benny's lane: amplitude, wavelength, phase (along), on (w)
96	uniform vec4 uBand2;      // r18 m07band: reach of Benny's lane (lane ± steer + body), cyan core half-width, min band width, foam-edge wobble
97	uniform vec3 uPlC;        // r21 m07end: plunge river cyan core half-width ramp (along from, along to, half-width)
98	uniform float uCloudSh;   // r22 m07cloud: the flat painted foam between the 3D foam mounds takes the mounds' periwinkle shade (0 = off)
99	uniform float uSatin;     // r22 '?m07satin=1': crisp painted satin streaks on the magenta bands (1 = on)
100	varying vec2 vUv;
101	varying vec4 vProj;
102	varying vec3 vW;
103	varying vec3 vN;
104	varying vec3 vL;
105	varying float vCtr;
106	${PROJ05_INVERSE}
107	// r22 m07satin: the painted magenta band is glossy satin with thin, bright, lens-shaped white-pink streaks running with the flow
108	// (white cores, soft pink glow). The band tile (92 px across a band up to ~1.8 u wide) has them, but magnified close to the camera
109	// (hard left / right, the foreground) they spread into soft smears. These streaks are world-anchored lanes of random lens
110	// segments at the painted scale, anti-aliased by fwidth and faded out where a lane gets thinner than ~2 px (far away the tile
111	// shows as before).
112	float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
113	vec2 satinLayer(float x, float y, float side, float w, float seed, float thr) {
114	  float u = x / w;
115	  float fw = fwidth(u);
116	  float aa = fw * 0.8 + 0.02;
117	  float lane = floor(u), fx = fract(u) - 0.5;
118	  float h1 = hash12(vec2(lane + seed * 17.0, side * 5.0 + seed));
119	  float L = 0.8 + 1.4 * h1;
120	  float yy = y / L + h1 * 9.0;
121	  float seg = floor(yy), fy = fract(yy);
122	  float h2 = hash12(vec2(lane * 1.37 + seg * 3.11 + seed, side * 2.0 + 0.5));
123	  float h3 = hash12(vec2(seg * 5.31 - lane * 0.7, side * 3.0 + seed * 1.9));
124	  float on = step(thr, h2);
125	  float c = (h3 - 0.5) * 0.3;
126	  float tp = pow(max(sin(3.14159 * fy), 0.0), 0.9);
127	  float hw = (0.16 + 0.2 * fract(h2 * 7.13)) * tp;
128	  float e = abs(fx - c);
129	  float halo = 1.0 - smoothstep(hw - aa, hw + aa + 0.14, e);
130	  float core = 1.0 - smoothstep(hw * 0.4 - aa, hw * 0.4 + aa, e);
131	  float k = on * (0.65 + 0.35 * fract(h3 * 13.7)) * (1.0 - smoothstep(0.35, 0.8, fw));
132	  return vec2(halo, core * tp) * k;
133	}
134	// x = world distance into the band from its inner edge, t = the same as a share of the band width, y = along, side = ±1
135	// → rgb: the painted satin base (deep magenta → hot pink → light pink ribbons following the flow), a: glow, + core in the 2nd value
136	vec4 satinBase(float t, float y, float side, out float crest) {
137	  float ph = t * 1.7 + 0.22 * sin(y * 0.6 + side * 1.1) + 0.1 * sin(y * 1.45 + 0.5 + side);
138	  float tone = 0.5 + 0.5 * sin(6.2831853 * ph);
139	  crest = smoothstep(0.62, 0.95, tone);
140	  vec3 deep = vec3(0.714, 0.094, 0.596), mid = vec3(0.94, 0.18, 0.784), light = vec3(0.969, 0.41, 0.953);
141	  vec3 c = mix(deep, mid, smoothstep(0.0, 0.55, tone));
142	  c = mix(c, light, smoothstep(0.55, 1.0, tone));
143	  return vec4(c, tone);
144	}
145	// r16 m07nearw: [foam | magenta | trim | cyan | cyan | trim | magenta | foam] across a winding centre line, world-anchored.
146	// Both banks are the painted lower-left band straightened (tools/match07/near_tiles_r16.py) at about the painted near
147	// scale; the right bank reads another stretch of the strip (no mirror image across the centre).
148	vec3 nearWater(float lx, float ctr, float along, float rc) {
149	  float d = lx - ctr;
150	  float R = uNearW.x, mw = uNearW.y;
151	  float Rc = R - mw;                       // cyan core half-width
152	  float Ro = R;                            // outer edge of the magenta band (foam beyond)
153	  if (uBand.w > 0.5) {
154	    // r18 m07band: the painted near river — a narrow glossy cyan core with THICK magenta satin bands close beside Benny, the
155	    // core sweeping in a world-anchored S off his lane (so the bands curve across the view as he swims, like the painted
156	    // S-sweeps); on the outside of each bend the band widens to cover everywhere Benny can steer (never foam under him)
157	    float S = uBand.x * sin(6.2831853 * (along - uBand.z) / uBand.y);
158	    d -= S;
159	    float reach = (d > 0.0 ? -S : S) + uBand2.x;
160	    Rc = rc;
161	    Ro = max(Rc + uBand2.z, reach);
162	  }
163	  float a = abs(d);
164	  float u;
165	  if (a < Rc) u = uNearM + (1.0 - uNearM) * (1.0 - a / Rc);
166	  else if (uBand.w > 0.5) {
167	    // the band tile's magenta columns spread across the whole (varying) band width (wide soft satin highlights where the band
168	    // is thick; no mirrored repeats, which read as a diamond lattice)
169	    u = uNearM * (1.0 - clamp((a - Rc) / max(Ro - Rc, 1e-3), 0.0, 1.0));
170	  } else u = uNearM * clamp((R - a) / mw, 0.0, 1.0);
171	  float v = along / uNearW.z;
172	  vec3 cL = texture2D(uNearTile, vec2(u, v)).rgb;
173	  vec3 cR = texture2D(uNearTile, vec2(u, v + 0.5)).rgb;
174	  vec3 river = mix(cL, cR, smoothstep(-0.32, 0.32, d));
175	  if (uSatin > 0.5) {
176	    // r22 m07satin: where the band is magnified close to the camera the smooth painted satin (tone ribbons following the flow)
177	    // takes over from the blurry tile; long white-pink glints run along the light crest ribbons (a few elsewhere)
178	    float xb = a - Rc, Wb = max(Ro - Rc, 1e-3);
179	    float t = clamp(xb / Wb, 0.0, 1.0), sd = sign(d);
180	    float bm = smoothstep(-0.01, 0.05, xb) * (1.0 - smoothstep(Wb - 0.06, Wb + 0.02, xb));
181	    float crest;
182	    vec4 sb = satinBase(t, along, sd, crest);
183	    float xw = xb + 0.04 * sin(along * 1.7 + sd * 2.0);
184	    vec2 g1 = satinLayer(xw, along, sd, 0.075, 0.0, 0.35);
185	    vec2 g2 = satinLayer(xw + 0.03, along * 1.13 + 0.7, sd, 0.12, 1.0, 0.8);
186	    vec2 gl = g1 * crest + g2;
187	    float procW = 1.0 - smoothstep(0.004, 0.016, fwidth(along));
188	    vec3 bandC = mix(river, sb.rgb, procW * 0.85);
189	    bandC = mix(bandC, vec3(1.0, 0.5, 0.96), 0.6 * min(gl.x, 1.0));
190	    bandC = mix(bandC, vec3(1.0, 0.95, 1.0), 0.9 * min(gl.y, 1.0));
191	    river = mix(river, bandC, bm);
192	  }
193	  R = Ro;
194	  // r18 m07band: a scalloped (puffy) foam line along the band's outer edge instead of a straight cut
195	  if (uBand.w > 0.5) R += uBand2.w * (0.6 * sin(along * 2.3 + sign(d) * 1.7) + 0.4 * sin(along * 5.1 + 0.4 + sign(d)));
196	  // painted foam clouds on the banks: two offset readings of the foam tile blended by a slow world mask (no wallpaper grid)
197	  vec2 fp = vec2(lx, along) / uNearW.w;
198	  vec3 f1 = texture2D(uFoamTile, fp).rgb;
199	  vec3 f2 = texture2D(uFoamTile, vec2(fp.y, -fp.x) * 0.77 + vec2(0.31, 0.57)).rgb;
200	  float fm = smoothstep(0.25, 0.75, 0.5 + 0.35 * sin(fp.x * 1.9 + 1.4 * sin(fp.y * 1.1)) + 0.25 * sin(fp.y * 1.6 + 0.8));
201	  vec3 foam = mix(f1, f2, fm);
202	  if (uCloudSh > 0.0) foam = mix(foam, foam * vec3(0.74, 0.77, 0.96), uCloudSh);
203	  return mix(river, foam, smoothstep(R - 0.04, R + 0.10, a));
204	}
205	// r16 m07wfoam: the painted foam clouds piled where the tube wall meets the water (no hard wall / floor edge when steering hard);
206	// a scalloped cloud-top line along the wall, world-anchored, the foam tile from the lower-right painted bank
207	vec3 wallFoam(vec3 c, float hy, float along, float side) {
208	  float k = along * 1.35 + side * 3.1;
209	  float b1 = pow(abs(sin(k + 0.8 * sin(along * 0.43 + side))), 0.55);
210	  float b2 = pow(abs(sin(k * 2.3 + 1.7)), 0.6);
211	  float hE = uWF.x + uWF.y * (0.65 * b1 + 0.35 * b2);
212	  float f = 1.0 - smoothstep(hE - 0.05, hE + 0.03, hy);
213	  vec3 foam = texture2D(uFoamTile, vec2(along, hy + side * 0.37) / 1.1).rgb;
214	  foam *= 0.9 + 0.14 * smoothstep(hE - 0.3, hE, hy);   // brighter cloud tops, softer shade toward the water
215	  return mix(c, foam, f);
216	}
217	vec3 riverTile() {
218	  float u = (vL.x - uRiver.x) / (uRiver.y - uRiver.x);
219	  u = 1.0 - abs(mod(u, 2.0) - 1.0);                       // mirrored across the banks
220	  float v = fract((-vL.z - uRiver.z) / (uRiver.w - uRiver.z));
221	  return texture2D(uTile, vec2(u, v)).rgb;
222	}
223	vec3 tileColor() {
224	  // r21 '?m07end=1': the plunge river = the painted near river (glossy cyan core, thick magenta satin bands sweeping in the
225	  // world-anchored S, painted foam beyond) instead of the repeating river tile; uv = (lateral from the course centre, depth)
226	  // (the cyan core widens from the level stretch's ±uBand2.y to ±uPlC.z over uPlC.x..y along: down the drop the painted river
227	  // is about half cyan, a quarter magenta each side)
228	  if (uMode > 4.5) return nearWater(vUv.x, 0.0, vUv.y, mix(uBand2.y, uPlC.z, smoothstep(uPlC.x, uPlC.y, vUv.y)));
229	  // M3 '?m07tube=1' plunge surfaces (real geometry along the course): uv = (arc depth along the tube, angle / lateral)
230	  if (uMode > 3.5) {
231	    float u = (vUv.x - uRiver.x) / (uRiver.y - uRiver.x);
232	    u = 1.0 - abs(mod(u, 2.0) - 1.0);
233	    float v = fract((vUv.y - uRiver.z) / (uRiver.w - uRiver.z));
234	    return texture2D(uTile, vec2(u, v)).rgb;
235	  }
236	  if (uMode > 2.5) {
237	    float u = fract((vUv.x - uTube.z) / uTube.w);
238	    float v = clamp((vUv.y - uTheta.x) / (uTheta.y - uTheta.x), 0.0, 1.0);
239	    return texture2D(uTile, vec2(u, v)).rgb;
240	  }
241	  if (uMode > 1.5) {
242	    if (uNearOn > 0.5) return nearWater(vL.x, vCtr, -vL.z, uBand2.y);
243	    return riverTile();
244	  }
245	  if (uMode > 0.5) {
246	    float a = atan(vL.y - uTube.y, vL.x - uTube.x);
247	    if (a < -1.5707963) a += 6.2831853;
248	    float v = clamp((a - uTheta.x) / (uTheta.y - uTheta.x), 0.0, 1.0);
249	    float u = fract((-vL.z - uTube.z) / uTube.w);
250	    vec3 wc = texture2D(uTile, vec2(u, v)).rgb;
251	    if (uWF.z > 0.5) wc = wallFoam(wc, vL.y, -vL.z, sign(vL.x - uTube.x));
252	    return wc;
253	  }
254	  vec3 n = abs(normalize(vN)); n /= max(n.x + n.y + n.z, 1e-4);
255	  vec3 p = vL * uPatchK;
256	  vec3 g = texture2D(uTile, p.zy).rgb * n.x + texture2D(uTile, p.xz).rgb * n.y + texture2D(uTile, p.xy).rgb * n.z;
257	  if (uGoldLit > 0.5) {
258	    vec3 nw = normalize(vN); vec3 vv = normalize(cameraPosition - vW);
259	    if (dot(nw, vv) < 0.0) nw = -nw;
260	    // saturated polished gold (the painted paddles' orange-gold), the patch only adds texture variation
261	    float lum = dot(g, vec3(0.299, 0.587, 0.114));
262	    float dif = 0.25 + 0.85 * max(dot(nw, uKey), 0.0);
263	    float spec = pow(max(dot(reflect(-uKey, nw), vv), 0.0), 24.0);
264	    float rim = pow(1.0 - max(dot(nw, vv), 0.0), 2.0);
265	    g = vec3(1.0, 0.58, 0.18) * (0.55 + 0.6 * lum) * dif + vec3(1.0, 0.9, 0.62) * (0.8 * spec + 0.45 * rim);
266	  }
267	  return g;
268	}
269	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
270	void main() {
271	  if (uClip > 0.0 && uMode < 2.5 && -vL.z > uClip) discard;
272	  vec3 pc = tileColor();
273	  if (uMode > 2.5) {
274	    // plunge surfaces: never in the approved picture → the ring-bay / river tiles only, world-anchored
275	    float a = uMode > 3.5 ? 1.0 - smoothstep(uFade.x, uFade.y, vUv.y) : 1.0;
276	    if (a < 0.003) discard;
277	    gl_FragColor = vec4(pjInverse(pc), a);
278	    return;
279	  }
280	  vec3 t = pc;
281	  vec3 nn = normalize(vN);
282	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
283	  // stretch + magnification guard: the projection is used where the current view sees the surface no more face-on and
284	  // no more magnified than the approved view did (incidence-cosine ratio x distance ratio = 1 in the approved view)
285	  float mag = (cc / max(cp, 1e-3)) * (distance(uProjPos, vW) / max(distance(cameraPosition, vW), 1e-3));
286	  float keep = 1.0 - smoothstep(uGuard.x, uGuard.y, mag);
287	  if (vProj.w > 0.0) {
288	    vec3 ndc = vProj.xyz / vProj.w;
289	    vec2 uv = ndc.xy * 0.5 + 0.5;
290	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
291	      float vis = 1.0;
292	      if (uUseDepth > 0.5) {
293	        float zs = linZ(texture2D(uDepth, uv).r), zf = linZ(ndc.z * 0.5 + 0.5);
294	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
295	      }
296	      float w = vis * keep;
297	      // M2 '?m07fill=1': on the water, the provisional fill (Benny / coins in the picture) gives way to the river tile
298	      if (uFillTile > 0.5 && uMode > 1.5) w *= 1.0 - texture2D(uFill, uv).r;
299	      // M2 '?m07ang=1': painted relief (ring flanges, paddles) flattened on the proxy doubles when seen from another
300	      // direction: use the picture only where the view direction is close to the approved view's (identical there)
301	      if (uAng.x > 0.0) w *= smoothstep(uAng.y, uAng.x, dot(normalize(cameraPosition - vW), normalize(uProjPos - vW)));
302	      // m07gold (round 4): the paddle blocks show the picture only near the approved view direction; seen from beside or
303	      // below while passing they are solid polished gold (no picture of the wall smeared over their faces)
304	      if (uGoldLit > 0.5 && uMode < 0.5) w *= smoothstep(0.970, 0.995, dot(normalize(cameraPosition - vW), normalize(uProjPos - vW)));
305	      // r16 m07nearw: where the approved view itself looks (no magnification) the provisional fill keeps the old river tile, so
306	      // the approved start view stays exactly as it was; the painted near river takes over as the view magnifies the water
307	      vec3 pcf = pc;
308	      if (uNearOn > 0.5 && uMode > 1.5) pcf = mix(pc, riverTile(), keep * vis);
309	      t = mix(pcf, texture2D(uPlate, uv).rgb, w);
310	    }
311	  }
312	  gl_FragColor = vec4(pjInverse(t), 1.0);
313	}`;
314	
315	
316	// r21 '&m07cloud=1': REAL 3D puffy foam clouds on both banks (the painted foam: soft glossy cumulus lobes, white tops, lavender-blue
317	// undersides, small bubbly lobes at the river edge). Each lobe is a sphere impostor: a camera-facing quad, ray-traced in the
318	// fragment shader (true round silhouette, sphere normal and sphere depth, so lobes overlap each other and sit IN the water with a
319	// round contact line). 2 triangles per lobe.
320	const CLOUD_VERT = /* glsl */ `
321	attribute vec4 aLobe;     // centre (group-local), radius
322	attribute vec3 aTone;     // brightness jitter, surface seed, height in the mound (0 = sunk base dome .. 1 = top bump)
323	uniform vec2 uGuard;
324	uniform vec3 uProjPos;
325	uniform float uClip;
326	uniform float uMagOn;     // 1 = level stretch: a lobe rises only where the moving view magnifies the water past what the approved view showed
327	uniform float uCScale;
