float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
// r23 m07satin: the painted satin's tone ribbons are ~0.3 u apart at the painted near scale (3–4 light ribbons across the near
// band), meandering gently with the flow and now and then merging; ph = ribbon coordinate (1 per ribbon), world-anchored
float satinPh(float xb, float y, float sd) {
  return xb / 0.3 + 0.55 * sin(y * 0.45 + sd * 1.3) + 0.3 * sin(y * 1.1 + xb * 2.3 + sd * 0.7);
}
// a pointed, lens-shaped white flare (white core, soft pink glow) on ribbon lanes: u = lane coordinate (1 per lane, the flare runs
// along fract(u) = 0.5), y = along; L = segment length range, thr = share of segments left dark, wc / wg = core / glow half-width
// (lane units). Anti-aliased by fwidth; fades out where a lane gets thinner than a few pixels (far away the tile shows as before).
vec2 satinFlare(float u, float y, float side, float seed, vec2 L, float thr, float wc, float wg) {
  float fw = fwidth(u);
  float aa = fw * 0.7;
  float lane = floor(u), fx = fract(u) - 0.5;
  float h1 = hash12(vec2(lane + seed * 17.0, side * 5.0 + seed));
  float Ls = L.x + (L.y - L.x) * h1;
  float yy = y / Ls + h1 * 9.0;
  float seg = floor(yy), fy = fract(yy);
  float h2 = hash12(vec2(lane * 1.37 + seg * 3.11 + seed, side * 2.0 + 0.5));
  float h3 = hash12(vec2(seg * 5.31 - lane * 0.7, side * 3.0 + seed * 1.9));
  float on = step(thr, h2);
  // off-centre bulge (the flare is fattest a little ahead of its middle) and pointed ends
  float m = 0.35 + 0.3 * h3;
  float tp = fy < m ? fy / m : (1.0 - fy) / (1.0 - m);
  float tc = pow(clamp(tp, 0.0, 1.0), 1.25), tg = pow(clamp(tp, 0.0, 1.0), 0.7);
  float c = (h3 - 0.5) * 0.12;
  float e = abs(fx - c);
  float sz = 0.7 + 0.6 * fract(h2 * 7.13);
  float hg = wg * sz * tg, hc = wc * sz * tc;
  float glow = 1.0 - smoothstep(0.0, hg + aa, e);
  float core = 1.0 - smoothstep(hc - aa, hc + aa, e);
  float k = on * (0.7 + 0.3 * fract(h3 * 13.7)) * (1.0 - smoothstep(0.08, 0.22, fw));
